import { useState } from 'react';

const TOOLS = [
  { id: 'pen',      icon: '✏️', label: 'Pen' },
  { id: 'eraser',   icon: '⬜', label: 'Eraser' },
  { id: 'rect',     icon: '▭',  label: 'Rectangle' },
  { id: 'circle',   icon: '○',  label: 'Circle' },
  { id: 'line',     icon: '╱',  label: 'Line' },
  { id: 'text',     icon: 'T',  label: 'Text' },
];

const COLORS = ['#FFFFFF','#F87171','#FBBF24','#34D399','#60A5FA','#A78BFA','#000000'];

export default function Toolbar({ tool, setTool, color, setColor, strokeSize, setStrokeSize, onUndo, onRedo, onExportPNG, onExportPDF }) {
  const [showExport, setShowExport] = useState(false);

  return (
    <div className="fixed left-1/2 bottom-6 -translate-x-1/2 z-50 flex items-center gap-2
                    bg-zinc-900 border border-zinc-700 rounded-2xl px-4 py-2 shadow-2xl select-none">
      {/* Tool buttons */}
      {TOOLS.map(t => (
        <button
          key={t.id}
          title={t.label}
          onClick={() => setTool(t.id)}
          className={`w-9 h-9 rounded-xl text-base flex items-center justify-center transition-colors
            ${tool === t.id
              ? 'bg-indigo-600 text-white'
              : 'text-zinc-400 hover:bg-zinc-800 hover:text-white'}`}
        >
          {t.icon}
        </button>
      ))}

      {/* Divider */}
      <div className="w-px h-6 bg-zinc-700 mx-1" />

      {/* Color swatches */}
      <div className="flex gap-1">
        {COLORS.map(c => (
          <button
            key={c}
            onClick={() => setColor(c)}
            style={{ background: c }}
            className={`w-5 h-5 rounded-full border-2 transition-transform
              ${color === c ? 'border-white scale-110' : 'border-transparent'}`}
          />
        ))}
      </div>

      {/* Divider */}
      <div className="w-px h-6 bg-zinc-700 mx-1" />

      {/* Stroke size */}
      <input
        type="range" min={1} max={24} value={strokeSize}
        onChange={e => setStrokeSize(Number(e.target.value))}
        className="w-20 accent-indigo-500"
      />

      {/* Divider */}
      <div className="w-px h-6 bg-zinc-700 mx-1" />

      {/* Undo / Redo */}
      <button onClick={onUndo} title="Undo" className="w-9 h-9 rounded-xl text-zinc-400 hover:bg-zinc-800 hover:text-white flex items-center justify-center text-lg">↩</button>
      <button onClick={onRedo} title="Redo" className="w-9 h-9 rounded-xl text-zinc-400 hover:bg-zinc-800 hover:text-white flex items-center justify-center text-lg">↪</button>

      {/* Export dropdown */}
      <div className="relative">
        <button
          onClick={() => setShowExport(v => !v)}
          className="w-9 h-9 rounded-xl text-zinc-400 hover:bg-zinc-800 hover:text-white flex items-center justify-center text-sm"
          title="Export"
        >⬇</button>
        {showExport && (
          <div className="absolute bottom-12 right-0 bg-zinc-900 border border-zinc-700 rounded-xl overflow-hidden text-sm text-zinc-300 shadow-xl">
            <button onClick={() => { onExportPNG(); setShowExport(false); }}
              className="block w-full px-4 py-2 hover:bg-zinc-800 text-left">Export PNG</button>
            <button onClick={() => { onExportPDF(); setShowExport(false); }}
              className="block w-full px-4 py-2 hover:bg-zinc-800 text-left">Export PDF</button>
          </div>
        )}
      </div>
    </div>
  );
}
